fn field_schema(field: &FieldDescriptor, visited: &mut Vec<String>) -> Value {
    if field.is_map() {
        let value_schema = match field.kind() {
            Kind::Message(entry) => match entry.map_entry_value_field().kind() {
                k => kind_schema(&k, visited),
            },
            _ => json!({}),
        };
