1	//! ChatService gRPC server implementation.
2	//!
3	//! Implements the `op_chat.chat.ChatService` trait from `chat.proto`.
4	//!
5	//! Architecture:
6	//! - zeroclaw owns provider/model routing (OD-28) — SendRequest carries them.
7	//! - gemma_brain routes to the selected model and applies compliance tags.
8	//! - The chatbot is a DELEGATOR — forced tool calling is mandatory; even user
9	//!   responses are emitted as tool calls (respond_to_user).
10	//! - Chat persistence flows through the memory loop → cognitive-mcp.
11	//! - The agent loop is bounded (≥50 steps) and cancellable.
12	
13	use std::pin::Pin;
14	use std::sync::Arc;
15	
16	use tokio::sync::Mutex;
17	use tokio_stream::wrappers::ReceiverStream;
18	use tokio_stream::Stream;
19	use tonic::{Request, Response, Status};
20	use tracing::{info, warn};
21	
22	use crate::orchestration::proto::op_chat_chat::{
23	    chat_frame, chat_service_server::ChatService, ApproveRequest, ApproveResponse, CancelRequest,
24	    CancelResponse, ChatFrame, Heartbeat, SendRequest, StreamDone, UiMessagePart,
25	};
26	
27	/// Shared state for the ChatService.
28	pub struct ChatServiceImpl {
29	    /// Active conversation cursors for cancel support.
30	    cancellations: Arc<Mutex<std::collections::HashMap<String, tokio::sync::watch::Sender<bool>>>>,
31	    /// Pending approvals: tool_call_id -> oneshot sender.
32	    approvals: Arc<Mutex<std::collections::HashMap<String, tokio::sync::oneshot::Sender<bool>>>>,
33	}
34	
35	impl ChatServiceImpl {
36	    pub fn new() -> Self {
37	        Self {
38	            cancellations: Arc::new(Mutex::new(Default::default())),
39	            approvals: Arc::new(Mutex::new(Default::default())),
40	        }
41	    }
42	}
43	
44	impl Default for ChatServiceImpl {
45	    fn default() -> Self {
46	        Self::new()
47	    }
48	}
49	
50	type ChatStream = Pin<Box<dyn Stream<Item = Result<ChatFrame, Status>> + Send + 'static>>;
51	
52	#[async_trait::async_trait]
53	impl ChatService for ChatServiceImpl {
54	    type SendStream = ChatStream;
55	
56	    async fn send(
57	        &self,
58	        request: Request<SendRequest>,
59	    ) -> Result<Response<Self::SendStream>, Status> {
60	        let req = request.into_inner();
61	        let conversation_id = req.conversation_id.clone();
62	        let provider = req.provider.clone();
63	        let model = req.model.clone();
64	
65	        info!(
66	            conversation_id = %conversation_id,
67	            provider = %provider,
68	            model = %model,
69	            "ChatService.Send — streaming chat completion"
70	        );
71	
72	        // Parse ui_messages from JSON bytes.
73	        let ui_messages: Vec<serde_json::Value> = serde_json::from_slice(&req.ui_messages)
74	            .map_err(|e| Status::invalid_argument(format!("Invalid ui_messages JSON: {e}")))?;
75	
76	        // Set up cancellation channel.
77	        let (cancel_tx, _cancel_rx) = tokio::sync::watch::channel(false);
78	        {
79	            let mut cancellations = self.cancellations.lock().await;
80	            cancellations.insert(conversation_id.clone(), cancel_tx);
81	        }
82	
83	        // Cursor for monotonic frame ordering.
84	        let cursor = std::sync::atomic::AtomicU64::new(0);
85	
86	        let (tx, rx) = tokio::sync::mpsc::channel::<Result<ChatFrame, Status>>(64);
87	
88	        let cancellations = self.cancellations.clone();
89	        let conv_id = conversation_id.clone();
90	
91	        tokio::spawn(async move {
92	            let bump = || cursor.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
93	            // Emit heartbeat immediately so the client knows the stream is alive.
94	            let _ = tx
95	                .send(Ok(ChatFrame {
96	                    cursor: bump(),
97	                    body: Some(chat_frame::Body::Heartbeat(Heartbeat {
98	                        server_time_ms: chrono::Utc::now().timestamp_millis() as u64,
99	                    })),
100	                }))
101	                .await;
102	
103	            // TODO: Wire to gemma_brain routing + ForcedToolPipeline.
104	            //
105	            // The pipeline will:
106	            // 1. Build ChatRequest with tool_choice: Required
107	            // 2. Route through gemma_brain to the selected provider/model
108	            // 3. For each ModelPart yielded:
109	            //    - Text → ChatFrame::Part(text)
110	            //    - ToolCall → ChatFrame::Part(tool-call) + ApprovalRequired if needed
111	            //    - ToolResult → ChatFrame::Part(tool-result)
112	            //    - Reasoning → ChatFrame::Part(reasoning)
113	            // 4. Feed completed transcript to MemoryLoop for persistence
114	            // 5. Bounded at ≥50 steps, cancellable via cancel_rx
115	
116	            // Placeholder: echo back the last user message as a reasoning part
117	            // so the client can verify the stream is working.
118	            if let Some(last_msg) = ui_messages.last() {
119	                let role = last_msg
120	                    .get("role")
121	                    .and_then(|v| v.as_str())
122	                    .unwrap_or("user");
123	                let content = last_msg
124	                    .get("content")
125	                    .and_then(|v| v.as_str())
126	                    .unwrap_or("");
127	
128	                let payload = serde_json::json!({
129	                    "type": "text",
130	                    "text": format!(
131	                        "[ChatService stub] Received message from {role} via {provider}/{model}. \
132	                         Delegation pipeline not yet wired. Message: {content}"
133	                    )
134	                });
135	
136	                let _ = tx
137	                    .send(Ok(ChatFrame {
138	                        cursor: bump(),
139	                        body: Some(chat_frame::Body::Part(UiMessagePart {
140	                            message_id: uuid::Uuid::new_v4().to_string(),
141	                            role: "assistant".to_string(),
142	                            kind: "reasoning".to_string(),
143	                            payload: serde_json::to_vec(&payload).unwrap_or_default(),
144	                        })),
145	                    }))
146	                    .await;
147	            }
148	
149	            // Stream done.
150	            let _ = tx
151	                .send(Ok(ChatFrame {
152	                    cursor: bump(),
153	                    body: Some(chat_frame::Body::Done(StreamDone {
154	                        conversation_id: conv_id.clone(),
155	                        total_parts: 1,
156	                    })),
157	                }))
158	                .await;
159	
160	            // Cleanup cancellation registration.
161	            {
162	                let mut cancellations = cancellations.lock().await;
163	                cancellations.remove(&conv_id);
164	            }
165	        });
166	
167	        Ok(Response::new(Box::pin(ReceiverStream::new(rx))))
168	    }
169	
170	    async fn approve(
171	        &self,
172	        request: Request<ApproveRequest>,
173	    ) -> Result<Response<ApproveResponse>, Status> {
174	        let req = request.into_inner();
175	        info!(
176	            conversation_id = %req.conversation_id,
177	            tool_call_id = %req.tool_call_id,
178	            approved = req.approved,
179	            "ChatService.Approve"
180	        );
181	
182	        // Deliver the approval decision to the pending tool call.
183	        let mut approvals = self.approvals.lock().await;
184	        match approvals.remove(&req.tool_call_id) {
185	            Some(sender) => {
186	                let _ = sender.send(req.approved);
187	                Ok(Response::new(ApproveResponse {
188	                    success: true,
189	                    tool_call_id: req.tool_call_id,
190	                    error: None,
191	                }))
192	            }
193	            None => {
194	                warn!(
195	                    tool_call_id = %req.tool_call_id,
196	                    "Approval requested for unknown tool call"
